export interface MessageThreadParams {
        parentMessageId: number;
        parentMessage: BaseMessage | null;
        replyCount: number;
        lastReply: BaseMessage | null;
        updatedAt: number;
        conversationId: string;
        receiverType: string;
        receiverId: string;
        subscribed: boolean;
        unreadReplyCount: number | null;
        rawData: Record<string, any>;
}
