        category: string;
        parentMessageId?: number;
        quotedMessageId?: number;
        sentAt?: number;
        updatedAt?: number;
        deletedAt?: number;
        deliveredAt?: number;
        readAt?: number;
        sendState: SendState;
        failureReason?: string;
        localSortTs: number;
        source?: MessageSource;
        payload: unknown;
        tags: string[];
