        pinnedAt?: number | null;
        /** Who pinned it — a uid, or `app_system` for an admin pin. */
        pinnedBy?: string | null;
        /** When the logged-in user saved it (seconds), or `null` when known not to be saved. */
        savedAt?: number | null;
